{
  "test_cases": [
    {
      "id": "TC-045-01",
      "title": "Driver requests display of estimated front end position",
      "covers": [
        "ETC-045"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is powered on and connected to the train. The driver interface is active.",
      "test_inputs": "Driver command: 'Show Position'",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Driver issues the request to display the geographical position of the train's estimated front end.",
          "expected": "The OBU displays the geographical position relative to the track kilometre."
        }
      ]
    },
    {
      "id": "TC-045-02",
      "title": "Driver requests to stop display of estimated front end position",
      "covers": [
        "ETC-045"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The OBU is currently displaying the geographical position of the train's estimated front end.",
      "test_inputs": "Driver command: 'Hide Position'",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Driver issues the request to stop the display of the geographical position.",
          "expected": "The OBU stops displaying the geographical position of the train's estimated front end."
        }
      ]
    },
    {
      "id": "TC-045-03",
      "title": "Position display is not shown without driver request",
      "covers": [
        "ETC-045"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "OBU is powered on and connected to the train. The driver interface is active. No position display is currently active.",
      "test_inputs": "None",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Wait for a period of time without issuing any driver request for position display.",
          "expected": "The OBU does not display the geographical position of the train's estimated front end."
        }
      ]
    },
    {
      "id": "TC-046-01",
      "title": "Geographical position calculation includes distance travelled since reference",
      "covers": [
        "ETC-046"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU has a known geographical reference location (e.g., Track Km 10.000). The train has moved a known distance (e.g., 500 meters) from this reference.",
      "test_inputs": "Driver command: 'Show Position'",
      "assumptions": "The OBU correctly tracks the distance travelled since the last geographical reference location.",
      "steps": [
        {
          "no": 1,
          "action": "Driver requests the display of the geographical position.",
          "expected": "The displayed position is the reference location plus the distance travelled (e.g., Track Km 10.500)."
        }
      ]
    },
    {
      "id": "TC-046-02",
      "title": "Geographical position calculation with zero distance travelled",
      "covers": [
        "ETC-046"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "OBU has a known geographical reference location (e.g., Track Km 20.000). The train is stationary at this reference location.",
      "test_inputs": "Driver command: 'Show Position'",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Driver requests the display of the geographical position.",
          "expected": "The displayed position is equal to the reference location (e.g., Track Km 20.000)."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-ETC-050-01",
      "title": "MA uzunluğunu karşılamayan SSP/gradient ile MA kabul edilmemesi",
      "covers": [
        "ETC-050"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "OBU, MA işleme modundadır. Araçta mevcut SSP ve gradient verileri, gelen MA'nın tam uzunluğunu kapsamamaktadır.",
      "test_inputs": "Gelen MA mesajı, araçtaki mevcut SSP/gradient verilerinin kapsamından daha uzun bir mesafe içerir.",
      "assumptions": "MA'nın tam uzunluğu SUBSET-026 §3.7.2.3.1–3.7.2.3.2'ye göre hesaplanmıştır.",
      "steps": [
        {
          "no": 1,
          "action": "Araçtaki mevcut SSP ve gradient verilerinin MA'nın tam uzunluğunu kapsamadığı bir MA mesajı OBU'ya iletilir.",
          "expected": "OBU, MA'yı ve ilişkili mod profillerini kabul etmez."
        },
        {
          "no": 2,
          "action": "OBU'nun MA kabul durumu kontrol edilir.",
          "expected": "MA reddedilir ve ilgili hata durumu veya uyarı üretilir."
        }
      ]
    },
    {
      "id": "TC-ETC-050-02",
      "title": "MA ile birlikte gelen SSP/gradient verilerinin yetersiz olması durumunda MA kabul edilmemesi",
      "covers": [
        "ETC-050"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "OBU, MA işleme modundadır. Araçta mevcut SSP/gradient verileri yoktur veya MA ile birlikte gelen SSP/gradient verileri MA'nın tam uzunluğunu kapsamamaktadır.",
      "test_inputs": "MA mesajı, MA'nın tam uzunluğunu kapsamayan SSP ve gradient verileriyle birlikte iletilir.",
      "assumptions": "MA ile birlikte gelen SSP/gradient verilerinin kapsamı, MA'nın tam uzunluğundan kısadır.",
      "steps": [
        {
          "no": 1,
          "action": "MA'nın tam uzunluğunu kapsamayan SSP ve gradient verileriyle birlikte MA mesajı OBU'ya iletilir.",
          "expected": "OBU, MA'yı ve ilişkili mod profillerini kabul etmez."
        },
        {
          "no": 2,
          "action": "OBU'nun MA kabul durumu kontrol edilir.",
          "expected": "MA reddedilir ve ilgili hata durumu veya uyarı üretilir."
        }
      ]
    },
    {
      "id": "TC-ETC-050-03",
      "title": "MA uzunluğunu karşılayan SSP/gradient ile MA kabul edilmesi (Negatif Kontrol)",
      "covers": [
        "ETC-050"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "OBU, MA işleme modundadır. Araçtaki mevcut SSP ve gradient verileri, gelen MA'nın tam uzunluğunu kapsamaktadır.",
      "test_inputs": "Gelen MA mesajı, araçtaki mevcut SSP/gradient verilerinin kapsamı içinde kalan bir mesafe içerir.",
      "assumptions": "MA'nın tam uzunluğu SUBSET-026 §3.7.2.3.1–3.7.2.3.2'ye göre hesaplanmıştır ve SSP/gradient verileri bu uzunluğu tam olarak kapsamaktadır.",
      "steps": [
        {
          "no": 1,
          "action": "Araçtaki mevcut SSP ve gradient verilerinin MA'nın tam uzunluğunu kapsadığı bir MA mesajı OBU'ya iletilir.",
          "expected": "OBU, MA'yı ve ilişkili mod profillerini kabul eder."
        },
        {
          "no": 2,
          "action": "OBU'nun MA kabul durumu kontrol edilir.",
          "expected": "MA kabul edilir ve normal işleme devam eder."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "ETC-023: Geçersiz konum iken LRBG geçişinde geçerli konumun alınması",
      "covers": [
        "ETC-023"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU, tren konumunun geçersiz olduğunu raporlamaktadır. Araçta daha önce depolanmış geçersiz bir konum değeri bulunmaktadır.",
      "test_inputs": "LRBG geçiş sinyali.",
      "assumptions": "LRBG geçişinin OBU tarafından algılanması, geçerli bir konum verisinin üretilmesini tetikler.",
      "steps": [
        {
          "no": 1,
          "action": "Trenin LRBG'yi geçtiği simüle edilir.",
          "expected": "OBU, geçerli bir tren konumu depolar."
        },
        {
          "no": 2,
          "action": "OBU'daki depolanan konum durumu sorgulanır.",
          "expected": "Konum geçerli olarak işaretlenir ve önceki geçersiz konum verisi silinmiştir."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "ETC-023: Geçersiz konum iken ORBG geçişinde geçerli konumun alınması",
      "covers": [
        "ETC-023"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU, tren konumunun geçersiz olduğunu raporlamaktadır. Araçta daha önce depolanmış geçersiz bir konum değeri bulunmaktadır.",
      "test_inputs": "ORBG geçiş sinyali.",
      "assumptions": "ORBG geçişinin OBU tarafından algılanması, geçerli bir konum verisinin üretilmesini tetikler.",
      "steps": [
        {
          "no": 1,
          "action": "Trenin ORBG'yi geçtiği simüle edilir.",
          "expected": "OBU, geçerli bir tren konumu depolar."
        },
        {
          "no": 2,
          "action": "OBU'daki depolanan konum durumu sorgulanır.",
          "expected": "Konum geçerli olarak işaretlenir ve önceki geçersiz konum verisi silinmiştir."
        }
      ]
    },
    {
      "id": "TC-003",
      "title": "ETC-024: Aktif kabin varken tren yönünün belirlenmesi",
      "covers": [
        "ETC-024"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Trenin iki kabini vardır. Kabin A aktif, Kabin B pasiftir.",
      "test_inputs": "Aktif kabin bilgisi: Kabin A.",
      "assumptions": "Kabin A'nın aktif olması, trenin önünün Kabin A tarafı olarak tanımlanmasını sağlar.",
      "steps": [
        {
          "no": 1,
          "action": "OBU'nun tren yönü (orientation) parametresi sorgulanır.",
          "expected": "Tren yönü, aktif kabinin (Kabin A) tarafına göre tanımlanmıştır."
        }
      ]
    },
    {
      "id": "TC-004",
      "title": "ETC-024: Aktif kabin yokken son aktif kabine göre yönün belirlenmesi",
      "covers": [
        "ETC-024"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Trenin iki kabini vardır. Kabin A son olarak aktif olan kabindi, ancak şu an hiçbir kabin aktif değildir.",
      "test_inputs": "Aktif kabin bilgisi: Yok. Son aktif kabin: Kabin A.",
      "assumptions": "Hiçbir kabinin aktif olmaması durumunda, OBU son aktif kabinin (Kabin A) yönünü kullanır.",
      "steps": [
        {
          "no": 1,
          "action": "OBU'nun tren yönü (orientation) parametresi sorgulanır.",
          "expected": "Tren yönü, son aktif kabinin (Kabin A) tarafına göre tanımlanmıştır."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "Safe radio connection loss triggers reconnection attempt on same system",
      "covers": [
        "ETC-010"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is powered on and has an established safe radio connection with Radio System A. EURORADIO is functional.",
      "test_inputs": "Simulated loss of safe radio connection from EURORADIO.",
      "assumptions": "Radio System A is available and capable of accepting new connections.",
      "steps": [
        {
          "no": 1,
          "action": "Establish a safe radio connection between OBU and Radio System A.",
          "expected": "OBU status indicates an active safe radio connection with Radio System A."
        },
        {
          "no": 2,
          "action": "Simulate the loss of the safe radio connection via EURORADIO.",
          "expected": "OBU immediately initiates an attempt to set up a new safe radio connection with Radio System A."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "Repeated reconnection attempts until success",
      "covers": [
        "ETC-011"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU has lost the safe radio connection during an established communication session. The session is not terminated and the train has not passed the RIU termination location.",
      "test_inputs": "Simulated radio environment where the first N attempts fail and the (N+1)th attempt succeeds.",
      "assumptions": "The communication session remains active and the train is before the RIU termination location.",
      "steps": [
        {
          "no": 1,
          "action": "Simulate the loss of the safe radio connection.",
          "expected": "OBU starts repeating attempts to set up a new safe radio connection."
        },
        {
          "no": 2,
          "action": "Allow the first reconnection attempt to fail.",
          "expected": "OBU continues to repeat the attempt to set up a new safe radio connection."
        },
        {
          "no": 3,
          "action": "Allow the second reconnection attempt to succeed.",
          "expected": "A new safe radio connection is established and the OBU stops repeating the setup attempts."
        }
      ]
    },
    {
      "id": "TC-03",
      "title": "Reconnection attempts stop when session is terminated",
      "covers": [
        "ETC-011"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "OBU has lost the safe radio connection during an established communication session. The train has not passed the RIU termination location.",
      "test_inputs": "Simulated session termination signal.",
      "assumptions": "The session termination is valid and recognized by the OBU.",
      "steps": [
        {
          "no": 1,
          "action": "Simulate the loss of the safe radio connection.",
          "expected": "OBU starts repeating attempts to set up a new safe radio connection."
        },
        {
          "no": 2,
          "action": "Trigger the termination of the communication session.",
          "expected": "OBU stops repeating the attempts to set up a new safe radio connection."
        }
      ]
    },
    {
      "id": "TC-04",
      "title": "Reconnection attempts stop when train passes RIU termination location",
      "covers": [
        "ETC-011"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "OBU has lost the safe radio connection during an established communication session. An RIU order specifying a termination location is active. The session is not otherwise terminated.",
      "test_inputs": "Train position data simulating passage of the RIU termination location.",
      "assumptions": "The RIU order is correctly loaded and the location is defined.",
      "steps": [
        {
          "no": 1,
          "action": "Simulate the loss of the safe radio connection.",
          "expected": "OBU starts repeating attempts to set up a new safe radio connection."
        },
        {
          "no": 2,
          "action": "Simulate the train passing the location given in the RIU order to terminate the communication session.",
          "expected": "OBU stops repeating the attempts to set up a new safe radio connection."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "Güç açıldığında GSM-R kayıt talebinin gönderilmesi",
      "covers": [
        "ETC-015"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU kapalı durumdadır. GSM-R Mobil Terminal bağlıdır ve çalışır durumdadır.",
      "test_inputs": "",
      "assumptions": "GSM-R ağının mevcut olduğu varsayılır.",
      "steps": [
        {
          "no": 1,
          "action": "OBU güç açma komutu verilir.",
          "expected": "OBU, bağlı GSM-R Mobil Terminal için GSM-R Radyo Ağına kayıt talebi gönderir."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "Sürücünün yeni GSM-R Radyo Ağı kimliği girmesi üzerine kayıt talebi",
      "covers": [
        "ETC-015"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU çalışır durumdadır ve mevcut bir GSM-R ağına kayıtlıdır.",
      "test_inputs": "Yeni GSM-R Radyo Ağı kimliği (PLMN ID).",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Sürücü arayüzünden yeni bir GSM-R Radyo Ağı kimliği girilir.",
          "expected": "OBU, yeni girilen kimliğe sahip GSM-R Radyo Ağına kayıt talebi gönderir."
        }
      ]
    },
    {
      "id": "TC-03",
      "title": "Ray kenarı komutu üzerine GSM-R kayıt talebi",
      "covers": [
        "ETC-015"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU çalışır durumdadır ve GSM-R Mobil Terminal bağlıdır.",
      "test_inputs": "Ray kenarından gelen kayıt komutu mesajı.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Ray kenarından OBU'ya GSM-R kayıt komutu gönderilir.",
          "expected": "OBU, bağlı GSM-R Mobil Terminal için GSM-R Radyo Ağına kayıt talebi gönderir."
        }
      ]
    },
    {
      "id": "TC-04",
      "title": "Hafızada Radyo Ağı tipi yokken varsayılan tipin kullanılması",
      "covers": [
        "ETC-016"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU hafızasında Radyo Ağı tipi bulunmamaktadır (ilk güç açma veya sistem hatası sonrası).",
      "test_inputs": "",
      "assumptions": "OBU üzerinde varsayılan Radyo Ağı tipi yapılandırılmıştır.",
      "steps": [
        {
          "no": 1,
          "action": "OBU güç açılır ve radyo ağı tipi sorgulanır.",
          "expected": "OBU, yapılandırılmış varsayılan Radyo Ağı tipini kullanır."
        }
      ]
    },
    {
      "id": "TC-05",
      "title": "Kayıtlı olmayan radyo sistemi için güvenli bağlantı talebinin yapılmaması",
      "covers": [
        "ETC-017"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "OBU çalışır durumdadır. Depolanan Radyo Ağı tipi, takılı radyo sistemleri ve sürücünün tek radyo seçimi göz önüne alındığında, gerekli radyo sisteminin Radyo Ağına kayıtlı olmadığı bir senaryo hazırlanmıştır.",
      "test_inputs": "RBC ile oturum kurma komutu (ray kenarından).",
      "assumptions": "SUBSET-026 §3.5.6.7'de belirtilen koşullar sağlanmaktadır.",
      "steps": [
        {
          "no": 1,
          "action": "Ray kenarından RBC ile oturum kurma komutu gönderilir.",
          "expected": "OBU, güvenli radyo bağlantısı kurulumu talebinde bulunmaz."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-055-01",
      "title": "MA request includes all applicable reasons",
      "covers": [
        "ETC-055"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in a state where an MA request is triggered. Multiple MA request reasons are simultaneously applicable according to SUBSET-026 §3.8.2.1.1.",
      "test_inputs": "Configuration to trigger MA request with multiple applicable reasons (e.g., reason A and reason B).",
      "assumptions": "The specific reasons are defined in SUBSET-026 §3.8.2.1.1. The test environment allows monitoring of the MA request message content.",
      "steps": [
        {
          "no": 1,
          "action": "Trigger an MA request while multiple MA request reasons are applicable.",
          "expected": "The OBU sends an MA request to the RBC."
        },
        {
          "no": 2,
          "action": "Inspect the content of the sent MA request message.",
          "expected": "The MA request message contains all the applicable MA request reasons."
        }
      ]
    },
    {
      "id": "TC-055-02",
      "title": "MA request includes single applicable reason",
      "covers": [
        "ETC-055"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "OBU is in a state where an MA request is triggered. Only one MA request reason is applicable.",
      "test_inputs": "Configuration to trigger MA request with a single applicable reason.",
      "assumptions": "The specific reason is defined in SUBSET-026 §3.8.2.1.1.",
      "steps": [
        {
          "no": 1,
          "action": "Trigger an MA request while only one MA request reason is applicable.",
          "expected": "The OBU sends an MA request to the RBC."
        },
        {
          "no": 2,
          "action": "Inspect the content of the sent MA request message.",
          "expected": "The MA request message contains the single applicable MA request reason."
        }
      ]
    },
    {
      "id": "TC-056-01",
      "title": "MA request triggered by perturbation-location criterion",
      "covers": [
        "ETC-056"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is configured with a perturbation-location criterion. The train is moving towards the location defined by the criterion.",
      "test_inputs": "Train position data simulating the train front passing the perturbation location.",
      "assumptions": "The perturbation-location criterion is defined in SUBSET-026 §3.8.2.2.1. The location is known and can be simulated.",
      "steps": [
        {
          "no": 1,
          "action": "Simulate the train front approaching the location resulting from the perturbation-location criterion.",
          "expected": "No MA request is sent while the train front has not yet passed the location."
        },
        {
          "no": 2,
          "action": "Simulate the train front passing the location resulting from the perturbation-location criterion.",
          "expected": "The OBU triggers an MA request to the RBC."
        }
      ]
    },
    {
      "id": "TC-056-02",
      "title": "MA request triggered by Section timer/LOA speed timer criterion",
      "covers": [
        "ETC-056"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is configured with a Section timer/LOA speed timer criterion. The timer is running.",
      "test_inputs": "Time simulation to reach the moment defined by the timer criterion.",
      "assumptions": "The Section timer/LOA speed timer criterion is defined in SUBSET-026 §3.8.2.2.1. The timer duration is known.",
      "steps": [
        {
          "no": 1,
          "action": "Start the Section timer/LOA speed timer.",
          "expected": "No MA request is sent while the timer has not reached the defined moment."
        },
        {
          "no": 2,
          "action": "Simulate the passage of time until the moment resulting from the Section timer/LOA speed timer criterion is reached.",
          "expected": "The OBU triggers an MA request to the RBC."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "OBU initiates termination upon explicit trackside order",
      "covers": [
        "ETC-012"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "An active communication session is established between the OBU and the trackside (RBC).",
      "test_inputs": "Trackside sends a 'Termination of Communication Session' message.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "The trackside sends a 'Termination of Communication Session' message to the OBU.",
          "expected": "The OBU initiates the termination of the communication session."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "OBU does not initiate termination without trackside order or defined condition",
      "covers": [
        "ETC-012"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "An active communication session is established between the OBU and the trackside (RBC). No termination conditions defined in SUBSET-026 are fulfilled.",
      "test_inputs": "No trackside termination order is sent. No internal termination condition is triggered.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Wait for a duration sufficient to observe potential spontaneous termination, ensuring no trackside order or internal condition occurs.",
          "expected": "The OBU maintains the communication session and does not initiate termination."
        }
      ]
    },
