      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in Override mode. The train has lost valid position (e.g., after passing a balise group without reading it or due to GPS loss). The former EOA/LOA is known. The distance to be supervised is 0 m.",
      "test_inputs": "Odometer reading, estimated/max/min safe front end positions.",
      "assumptions": "The OBU allows simulation of 'no valid position' state and provides a diagnostic interface to observe the calculated remaining distance and the virtual train front position.",
      "steps": [
        {
          "no": 1,
          "action": "Initiate the supervision for the zero distance to the former EOA/LOA after Override.",
          "expected": "The OBU starts supervising a virtual train front position."
        },
        {
          "no": 2,
          "action": "Move the train forward by a known distance (e.g., 10 m) using the odometer.",
          "expected": "The OBU calculates the remaining distance as the supervised distance (0 m) minus the distance travelled, corrected by odometer under/over-reading. The virtual front position is updated accordingly."
        },
        {
          "no": 3,
          "action": "Query the OBU for the current remaining distance to the former EOA/LOA.",
          "expected": "The reported remaining distance reflects the movement away from the start point, adjusted for odometer errors as defined in §3.6.7.3."
        }
      ]
    },
    {
      "id": "TC-8",
      "title": "Supervision of Staff Responsible distance using virtual train front position",
      "covers": [
        "ETC-049"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in Staff Responsible mode. The Staff Responsible maximum distance is configured (e.g., 500 m). The train is at a known location.",
      "test_inputs": "Odometer reading, estimated/max/min safe front end positions.",
      "assumptions": "The OBU provides a diagnostic interface to observe the calculated remaining distance and the virtual train front position.",
      "steps": [
        {
          "no": 1,
          "action": "Start the Staff Responsible supervision.",
          "expected": "The OBU begins supervising the Staff Responsible distance using a virtual train front position."
        },
        {
          "no": 2,
          "action": "Move the train forward by a known distance (e.g., 100 m).",
          "expected": "The OBU updates the virtual train front position based on the estimated, max safe, and min safe front ends."
        },
        {
          "no": 3,
          "action": "Query the OBU for the remaining Staff Responsible distance.",
          "expected": "The remaining distance is calculated as the configured Staff Responsible distance minus the distance travelled, corrected by odometer under/over-reading as defined in §3.6.7.3."
        }
      ]
    },
    {
      "id": "TC-9",
      "title": "Odometer under-reading correction in virtual front position calculation",
      "covers": [
        "ETC-049"
      ],
      "type": "Hata",
      "priority": "Orta",
      "preconditions": "OBU is supervising a distance (e.g., Staff Responsible) using a virtual train front position. The odometer is configured to simulate an under-reading (e.g., reports 90% of actual distance).",
      "test_inputs": "Simulated odometer under-reading factor, actual distance travelled.",
      "assumptions": "The OBU allows configuration of odometer error simulation and provides a diagnostic interface to observe the corrected remaining distance.",
      "steps": [
        {
          "no": 1,
          "action": "Start the supervision for a known distance (e.g., 100 m).",
          "expected": "The OBU initializes the virtual train front position."
        },
        {
          "no": 2,
          "action": "Move the train by an actual distance of 50 m, but the odometer reports 45 m (10% under-reading).",
          "expected": "The OBU applies the correction for odometer under-reading as defined in §3.6.7.3."
        },
        {
          "no": 3,
          "action": "Query the OBU for the remaining distance.",
          "expected": "The remaining distance is calculated using the corrected distance travelled, not the raw odometer reading, ensuring the supervision reflects the true position within the allowed error bounds."
        }
      ]
    }
  ],
